33	/// The result of shaping text.
34	///
35	/// This type contains owned or borrowed shaped text runs, which can be
36	/// measured, used to reshape substrings more quickly and converted into a
37	/// frame.
38	#[derive(Clone)]
39	pub struct ShapedText<'a> {
40	    /// The start of the text in the full text.
41	    pub base: usize,
42	    /// The text that was shaped.
43	    pub text: &'a str,
44	    /// The text direction.
45	    pub dir: Dir,
46	    /// The text language.
47	    pub lang: Lang,
48	    /// The text region.
49	    pub region: Option<Region>,
50	    /// The text's style properties.
51	    pub styles: StyleChain<'a>,
52	    /// The font variant.
53	    pub variant: FontVariant,
54	    /// The shaped glyphs.
55	    pub glyphs: Glyphs<'a>,
56	}
57	
58	/// A copy-on-write collection of glyphs.
59	///
60	/// At the edges of the collection, there can be _trimmed_ glyphs for end-of-line
61	/// whitespace that should not affect layout, but should be emitted into the PDF
62	/// to keep things accessible.
63	///
64	/// These glyphs are not visible when deref-ing the `Glyphs` to a slice as they
65	/// should be ignored in almost all circumstances. They are only visible when
66	/// explicitly accessing [`all`](Self::all) glyphs.
67	#[derive(Clone)]
68	pub struct Glyphs<'a> {
69	    /// All glyphs, including the trimmed ones.
70	    inner: Cow<'a, [ShapedGlyph]>,
71	    /// The range of untrimmed glyphs.
72	    kept: Range,
73	}
74	
75	impl<'a> Glyphs<'a> {
76	    /// Create a borrowed glyph collection from an existing slice.
77	    ///
78	    /// This happens after reshaping.
79	    pub fn from_slice(glyphs: &'a [ShapedGlyph]) -> Self {
80	        Self {
81	            inner: Cow::Borrowed(glyphs),
82	            kept: 0..glyphs.len(),
83	        }
84	    }
85	
86	    /// Create an owned glyph collection from an vector.
87	    ///
88	    /// This happens after initial shaping.
89	    pub fn from_vec(glyphs: Vec<ShapedGlyph>) -> Self {
90	        let len = glyphs.len();
91	        Self { inner: Cow::Owned(glyphs), kept: 0..len }
92	    }
93	
94	    /// Clone the internal glyph data to make it modifiable. Should be avoided
95	    /// if possible on potentially borrowed glyphs as it can be expensive
96	    /// (benchmarks have shown ~10% slowdown on a text-heavy document if no
97	    /// borrowing is used).
98	    pub fn to_mut(&mut self) -> &mut [ShapedGlyph] {
99	        &mut self.inner.to_mut()[self.kept.clone()]
100	    }
101	
102	    /// Trims glyphs that satisfy the given condition from the start and end.
103	    ///
104	    /// Those glyphs will not be visible during normal operation anymore, only
105	    /// through [`all`](Self::all).
106	    pub fn trim(&mut self, f: impl FnMut(&ShapedGlyph) -> bool + Copy) {
107	        let (start, end) = self.inner.split_prefix_suffix(f);
108	        self.kept = start..end;
109	    }
110	
111	    /// Accesses all glyphs, not just the untrimmed ones.
112	    pub fn all(&self) -> &[ShapedGlyph] {
113	        self.inner.as_ref()
114	    }
115	
116	    /// Whether this contains neither kept nor trimmed glyphs.
117	    pub fn is_fully_empty(&self) -> bool {
118	        self.inner.is_empty()
119	    }
120	}
121	
122	impl Deref for Glyphs<'_> {
123	    type Target = [ShapedGlyph];
124	
125	    /// Returns only the kept (untrimmed) glyphs.
126	    fn deref(&self) -> &Self::Target {
127	        &self.inner[self.kept.clone()]
128	    }
129	}
130	
131	/// A single glyph resulting from shaping.
132	#[derive(Debug, Clone)]
133	pub struct ShapedGlyph {
134	    /// The font the glyph is contained in.
135	    pub font: FontInstance,
136	    /// The glyph's index in the font.
137	    pub glyph_id: u16,
138	    /// The advance width of the glyph.
139	    pub x_advance: Em,
140	    /// The horizontal offset of the glyph.
141	    pub x_offset: Em,
142	    /// The vertical offset of the glyph.
143	    pub y_offset: Em,
144	    /// The font size for the glyph.
145	    pub size: Abs,
146	    /// The adjustability of the glyph.
147	    pub adjustability: Adjustability,
148	    /// The byte range of this glyph's cluster in the full inline layout. A
149	    /// cluster is a sequence of one or multiple glyphs that cannot be separated
150	    /// and must always be treated as a union.
151	    ///
152	    /// The range values of the glyphs in a [`ShapedText`] should not overlap
153	    /// with each other, and they should be monotonically increasing (for
154	    /// left-to-right or top-to-bottom text) or monotonically decreasing (for
155	    /// right-to-left or bottom-to-top text).
156	    pub range: Range,
157	    /// Whether splitting the shaping result before this glyph would yield the
158	    /// same results as shaping the parts to both sides of `text_index`
159	    /// separately.
160	    pub safe_to_break: bool,
161	    /// The first char in this glyph's cluster.
162	    pub c: char,
163	    /// Whether this glyph is justifiable for CJK scripts.
164	    pub is_justifiable: bool,
165	    /// The script of the glyph.
166	    pub script: Script,
167	}
168	
169	#[derive(Debug, Default, Clone)]
170	pub struct Adjustability {
171	    /// The left and right stretchability
172	    pub stretchability: (Em, Em),
173	    /// The left and right shrinkability
174	    pub shrinkability: (Em, Em),
175	}
176	
177	impl ShapedGlyph {
178	    /// Whether the glyph is a space.
179	    pub fn is_space(&self) -> bool {
180	        is_space(self.c)
181	    }
182	
183	    /// Whether the glyph is justifiable.
184	    pub fn is_justifiable(&self) -> bool {
185	        // GB style is not relevant here.
186	        self.is_justifiable
187	    }
188	
189	    /// Whether the glyph is part of Chinese or Japanese script (i.e. CJ, not CJK).
190	    pub fn is_cj_script(&self) -> bool {
191	        is_cj_script(self.c, self.script)
192	    }
193	
194	    pub fn is_cjk_punctuation(&self) -> bool {
195	        self.is_cjk_left_aligned_punctuation(CjkPunctStyle::Gb)
196	            || self.is_cjk_right_aligned_punctuation()
197	            || self.is_cjk_center_aligned_punctuation(CjkPunctStyle::Gb)
198	    }
199	
200	    /// See <https://www.w3.org/TR/clreq/#punctuation_width_adjustment>
201	    pub fn is_cjk_left_aligned_punctuation(&self, style: CjkPunctStyle) -> bool {
202	        is_cjk_left_aligned_punctuation(
203	            self.c,
204	            self.x_advance,
205	            self.stretchability(),
206	            style,
207	        )
208	    }
209	
210	    /// See <https://www.w3.org/TR/clreq/#punctuation_width_adjustment>
211	    pub fn is_cjk_right_aligned_punctuation(&self) -> bool {
212	        is_cjk_right_aligned_punctuation(self.c, self.x_advance, self.stretchability())
213	    }
214	
215	    /// See <https://www.w3.org/TR/clreq/#punctuation_width_adjustment>
216	    pub fn is_cjk_center_aligned_punctuation(&self, style: CjkPunctStyle) -> bool {
217	        is_cjk_center_aligned_punctuation(self.c, style)
218	    }
219	
220	    /// Whether the glyph is a western letter or number.
221	    pub fn is_letter_or_number(&self) -> bool {
222	        matches!(self.c.script(), Script::Latin | Script::Greek | Script::Cyrillic)
223	            || matches!(self.c, '#' | '$' | '%' | '&')
224	            || self.c.is_ascii_digit()
225	    }
226	
227	    /// The amount by which the glyph's advance width is allowed to be shrunk or
228	    /// stretched to improve justification.
229	    pub fn base_adjustability(
230	        &self,
231	        style: CjkPunctStyle,
232	        limits: &JustificationLimits,
233	        font_size: Abs,
234	        stretchable: bool,
235	    ) -> Adjustability {
236	        let width = self.x_advance;
237	
238	        // Do not ever shrink away more than three quarters of the glyph. As the
239	        // width approaches zero, justification gets increasingly expensive and
240	        // if negative it may not terminate.
241	        let limited = |v: Em| v.min(width * 0.75);
242	
243	        if self.is_space() {
244	            // To a space, both the spacing and tracking limits apply, just like
245	            // `text.tracking` and `text.spacing` both apply to spaces.
246	            let max = limits.spacing().max + limits.tracking().max;
247	            let min = limits.spacing().min + limits.tracking().min;
248	            Adjustability {
249	                stretchability: (
250	                    Em::zero(),
251	                    (max - Rel::one())
252	                        .map(|length| Em::from_length(length, font_size))
253	                        .relative_to(width)
254	                        .max(Em::zero()),
255	                ),
256	                shrinkability: (
257	                    Em::zero(),
258	                    limited(
259	                        (Rel::one() - min)
260	                            .map(|length| Em::from_length(length, font_size))
261	                            .relative_to(width),
262	                    ),
263	                ),
264	            }
265	        } else if self.is_cjk_left_aligned_punctuation(style) {
266	            Adjustability {
267	                stretchability: (Em::zero(), Em::zero()),
268	                shrinkability: (Em::zero(), width / 2.0),
269	            }
270	        } else if self.is_cjk_right_aligned_punctuation() {
271	            Adjustability {
272	                stretchability: (Em::zero(), Em::zero()),
273	                shrinkability: (width / 2.0, Em::zero()),
274	            }
275	        } else if self.is_cjk_center_aligned_punctuation(style) {
276	            Adjustability {
277	                stretchability: (Em::zero(), Em::zero()),
278	                shrinkability: (width / 4.0, width / 4.0),
279	            }
280	        } else if stretchable {
281	            Adjustability {
282	                stretchability: (
283	                    Em::zero(),
284	                    Em::from_length(limits.tracking().max, font_size).max(Em::zero()),
285	                ),
286	                shrinkability: (
287	                    Em::zero(),
288	                    limited(Em::from_length(-limits.tracking().min, font_size)),
289	                ),
290	            }
291	        } else {
292	            Adjustability::default()
293	        }
294	    }
295	
296	    /// The stretchability of the character.
297	    pub fn stretchability(&self) -> (Em, Em) {
298	        self.adjustability.stretchability
299	    }
300	
301	    /// The shrinkability of the character.
302	    pub fn shrinkability(&self) -> (Em, Em) {
303	        self.adjustability.shrinkability
304	    }
305	
306	    /// Shrink the width of glyph on the left side.
307	    pub fn shrink_left(&mut self, amount: Em) {
308	        self.x_offset -= amount;
309	        self.x_advance -= amount;
310	        self.adjustability.shrinkability.0 -= amount;
311	    }
312	
313	    /// Shrink the width of glyph on the right side.
314	    pub fn shrink_right(&mut self, amount: Em) {
315	        self.x_advance -= amount;
316	        self.adjustability.shrinkability.1 -= amount;
317	    }
318	}
319	
320	impl<'a> ShapedText<'a> {
321	    /// Build the shaped text's frame.
322	    ///
323	    /// The `justification` defines how much extra advance width each
324	    /// [justifiable glyph](ShapedGlyph::is_justifiable) will get.
325	    pub fn build(
326	        &self,
327	        engine: &Engine,
328	        spans: &SpanMapper,
329	        justification_ratio: f64,
330	        extra_justification: Abs,
331	    ) -> Frame {
332	        let (top, bottom) = self.measure(engine);
333	        let size = Size::new(self.width(), top + bottom);
334	
335	        let mut offset = Abs::zero();
336	        let mut frame = Frame::soft(size);
337	        frame.set_baseline(top);
338	
339	        let size = self.styles.resolve(TextElem::size);
340	        let shift = self.styles.resolve(TextElem::baseline);
341	        let decos = self.styles.get_cloned(TextElem::deco);
342	        let fill = self.styles.get_ref(TextElem::fill);
343	        let stroke = self.styles.resolve(TextElem::stroke);
344	        let span_offset = self.styles.get(TextElem::span_offset);
345	
346	        let mut i = 0;
347	        for ((font, y_offset, glyph_size), group) in self
348	            .glyphs
349	            .all()
350	            .group_by_key(|g| (g.font.clone(), g.y_offset, g.size))
351	        {
352	            let mut range = group[0].range.clone();
353	            for glyph in group {
354	                range.start = range.start.min(glyph.range.start);
355	                range.end = range.end.max(glyph.range.end);
356	            }
357	
358	            let pos = Point::new(offset, top + shift - y_offset.at(size));
359	            let glyphs: Vec<Glyph> = group
360	                .iter()
361	                .map(|shaped: &ShapedGlyph| {
362	                    // Whether the glyph is _not_ trimmed end-of-line
363	                    // whitespace. Trimmed whitespace has its advance width and
364	                    // offset zeroed out and is not taken into account for
365	                    // justification.
366	                    let kept = self.glyphs.kept.contains(&i);
367	
368	                    let (x_advance, x_offset) = if kept {
369	                        let adjustability_left = if justification_ratio < 0.0 {
370	                            shaped.shrinkability().0
371	                        } else {
372	                            shaped.stretchability().0
373	                        };
374	                        let adjustability_right = if justification_ratio < 0.0 {
375	                            shaped.shrinkability().1
376	                        } else {
377	                            shaped.stretchability().1
378	                        };
379	
380	                        let justification_left = adjustability_left * justification_ratio;
381	                        let mut justification_right =
382	                            adjustability_right * justification_ratio;
383	                        if shaped.is_justifiable() {
384	                            justification_right +=
385	                                Em::from_abs(extra_justification, glyph_size);
386	                        }
387	
388	                        frame.size_mut().x += justification_left.at(glyph_size)
389	                            + justification_right.at(glyph_size);
390	
391	                        (
392	                            shaped.x_advance + justification_left + justification_right,
393	                            shaped.x_offset + justification_left,
394	                        )
395	                    } else {
396	                        (Em::zero(), Em::zero())
397	                    };
398	                    i += 1;
399	
400	                    // We may not be able to reach the offset completely if
401	                    // it exceeds u16, but better to have a roughly correct
402	                    // span offset than nothing.
403	                    let mut span = spans.span_at(shaped.range.start);
404	                    span.1 = span.1.saturating_add(span_offset.saturating_as());
405	
406	                    // |<---- a Glyph ---->|
407	                    //  -->|ShapedGlyph|<--
408	                    // +---+-----------+---+
409	                    // |   |  *********|   |
410	                    // |   |  *        |   |
411	                    // |   |  *    ****|   |
412	                    // |   |  *       *|   |
413	                    // |   |  *********|   |
414	                    // +---+--+--------+---+
415	                    //   A   B     C     D
416	                    // Note A, B, D could be positive, zero, or negative.
417	                    // A: justification_left
418	                    // B: ShapedGlyph's x_offset
419	                    //    (though a small part of the glyph may go inside B)
420	                    // B+C: ShapedGlyph's x_advance
421	                    // D: justification_right
422	                    // A+B: Glyph's x_offset
423	                    // A+B+C+D: Glyph's x_advance
424	                    Glyph {
425	                        id: shaped.glyph_id,
426	                        x_advance,
427	                        x_offset,
428	                        y_advance: Em::zero(),
429	                        y_offset: Em::zero(),
430	                        range: (shaped.range.start - range.start).saturating_as()
431	                            ..(shaped.range.end - range.start).saturating_as(),
432	                        span,
433	                    }
434	                })
435	                .collect();
436	
437	            let item = TextItem {
438	                font,
439	                size: glyph_size,
440	                lang: self.lang,
441	                region: self.region,
442	                fill: fill.clone(),
443	                stroke: stroke.clone().map(|s| s.unwrap_or_default()),
444	                text: self.text[range.start - self.base..range.end - self.base].into(),
445	                glyphs,
446	            };
447	
448	            let width = item.width();
449	            if decos.is_empty() {
450	                frame.push(pos, FrameItem::Text(item));
451	            } else {
452	                // Apply line decorations.
453	                frame.push(pos, FrameItem::Text(item.clone()));
454	                for deco in &decos {
455	                    decorate(&mut frame, deco, &item, width, shift, pos);
456	                }
457	            }
458	
459	            offset += width;
460	        }
461	
462	        frame.modify_text(self.styles);
463	        frame
464	    }
