466	    /// Computes the width of a run of glyphs relative to the font size,
467	    /// accounting for their individual scaling factors and other font metrics.
468	    pub fn width(&self) -> Abs {
469	        self.glyphs.iter().map(|g| g.x_advance.at(g.size)).sum()
470	    }
