472	    /// Measure the top and bottom extent of this text.
473	    pub fn measure(&self, engine: &Engine) -> (Abs, Abs) {
474	        let mut top = Abs::zero();
475	        let mut bottom = Abs::zero();
476	
477	        let size = self.styles.resolve(TextElem::size);
478	        let top_edge = self.styles.get(TextElem::top_edge);
479	        let bottom_edge = self.styles.get(TextElem::bottom_edge);
480	
481	        // Expand top and bottom by reading the font's vertical metrics.
482	        let mut expand = |font: &FontInstance, bounds: TextEdgeBounds| {
483	            let (t, b) = font.edges(top_edge, bottom_edge, size, bounds);
484	            top.set_max(t);
485	            bottom.set_max(b);
486	        };
487	
488	        if self.glyphs.is_fully_empty() {
489	            // When there are no glyphs, we just use the vertical metrics of the
490	            // first available font.
491	            let world = engine.world;
492	            let variations = self.styles.get_cloned(TextElem::variations);
493	            if let Some(font) = families(self.styles).find_map(|family| {
494	                world
495	                    .book()
496	                    .select(family.as_str(), self.variant)
497	                    .and_then(|id| world.font(id))
498	                    .map(|font| font.instantiate(self.variant, size, &variations))
499	            }) {
500	                expand(&font, TextEdgeBounds::Zero);
501	            }
502	        } else {
503	            for g in self.glyphs.iter() {
504	                expand(&g.font, TextEdgeBounds::Glyph(g.glyph_id));
505	            }
506	        }
507	
508	        (top, bottom)
509	    }
