579	    /// Creates shaped text containing a hyphen.
580	    ///
581	    /// If `soft` is true, the item will map to plain text as a soft hyphen.
582	    /// Otherwise, it will map to a normal hyphen.
583	    pub fn hyphen(
584	        engine: &Engine,
585	        fallback: bool,
586	        base: &ShapedText<'a>,
587	        pos: usize,
588	        soft: bool,
589	    ) -> Option<Self> {
590	        let world = engine.world;
591	        let book = world.book();
592	        let fallback_func = if fallback {
593	            Some(|| book.select_fallback(None, base.variant, "-"))
594	        } else {
595	            None
596	        };
597	        let mut chain = families(base.styles)
598	            .filter(|family| family.covers().is_none_or(|c| c.is_match("-")))
599	            .map(|family| book.select(family.as_str(), base.variant))
600	            .chain(fallback_func.iter().map(|f| f()))
601	            .flatten();
602	
603	        chain.find_map(|id| {
604	            let size = base.styles.resolve(TextElem::size);
605	            let variations = base.styles.get_cloned(TextElem::variations);
606	            let font = world
607	                .font(id)
608	                .map(|font| font.instantiate(base.variant, size, &variations))?;
609	            let ttf = font.ttf();
610	            let glyph_id = ttf.glyph_index('-')?;
611	            let x_advance = font.to_em(ttf.glyph_hor_advance(glyph_id)?);
612	            let (c, text) = if soft { (SHY, SHY_STR) } else { (HYPHEN, HYPHEN_STR) };
613	
614	            Some(ShapedText {
615	                base: pos,
616	                text,
617	                dir: base.dir,
618	                lang: base.lang,
619	                region: base.region,
620	                styles: base.styles,
621	                variant: base.variant,
622	                glyphs: Glyphs::from_vec(vec![ShapedGlyph {
623	                    font,
624	                    glyph_id: glyph_id.0,
625	                    x_advance,
626	                    x_offset: Em::zero(),
627	                    y_offset: Em::zero(),
628	                    size,
629	                    adjustability: Adjustability::default(),
630	                    range: pos..pos + text.len(),
631	                    safe_to_break: true,
632	                    c,
633	                    is_justifiable: false,
634	                    script: Script::Common,
635	                }]),
636	            })
637	        })
638	    }
