640	    /// Find the subslice of glyphs that represent the given text range if both
641	    /// sides are safe to break.
642	    fn slice_safe_to_break(&self, text_range: Range) -> Option<&[ShapedGlyph]> {
643	        let Range { mut start, mut end } = text_range;
644	        if !self.dir.is_positive() {
645	            std::mem::swap(&mut start, &mut end);
646	        }
647	
648	        let left = self.find_safe_to_break(start)?;
649	        let right = self.find_safe_to_break(end)?;
650	        Some(&self.glyphs[left..right])
651	    }
652	
653	    /// Find the glyph offset matching the text index that is most towards the
654	    /// start of the text and safe-to-break.
655	    fn find_safe_to_break(&self, text_index: usize) -> Option<usize> {
656	        let ltr = self.dir.is_positive();
657	
658	        // Handle edge cases.
659	        let len = self.glyphs.len();
660	        if text_index == self.base {
661	            return Some(if ltr { 0 } else { len });
662	        } else if text_index == self.base + self.text.len() {
663	            return Some(if ltr { len } else { 0 });
664	        }
665	
666	        // Find any glyph with the text index.
667	        let found = self.glyphs.binary_search_by(|g: &ShapedGlyph| {
668	            let ordering = g.range.start.cmp(&text_index);
669	            if ltr { ordering } else { ordering.reverse() }
670	        });
671	
672	        let mut idx = match found {
673	            Ok(idx) => idx,
674	            Err(idx) => {
675	                // Handle the special case where we break before a '\n'
676	                //
677	                // For example: (assume `a` is a CJK character with three bytes)
678	                // text:  " a     \n b  "
679	                // index:   0 1 2 3  4 5
680	                // text_index:    ^
681	                // glyphs:  0     .  1
682	                //
683	                // We will get found = Err(1), because '\n' does not have a
684	                // glyph. But it's safe to break here. Thus the following
685	                // condition:
686	                // - glyphs[0].end == text_index == 3
687	                // - text[3] == '\n'
688	                return (idx > 0
689	                    && self.glyphs[idx - 1].range.end == text_index
690	                    && self.text[text_index - self.base..].starts_with('\n'))
691	                .then_some(idx);
692	            }
693	        };
694	
695	        // Search for the start-most glyph with the text index. This means
696	        // we take empty range glyphs at the start and leave those at the end
697	        // for the next line.
698	        let dec = if ltr { usize::checked_sub } else { usize::checked_add };
699	        while let Some(next) = dec(idx, 1) {
700	            if self.glyphs.get(next).is_none_or(|g| g.range.start != text_index) {
701	                break;
702	            }
703	            idx = next;
704	        }
705	
706	        // RTL needs offset one because the left side of the range should be
707	        // exclusive and the right side inclusive, contrary to the normal
708	        // behaviour of ranges.
709	        self.glyphs[idx].safe_to_break.then_some(idx + usize::from(!ltr))
710	    }
711	}
