719	/// Group a range of text by BiDi level and script, shape the runs and generate
720	/// items for them.
721	pub fn shape_range<'a>(
722	    items: &mut Vec<(Range, Item<'a>)>,
723	    engine: &Engine,
724	    text: &'a str,
725	    bidi: &BidiInfo<'a>,
726	    range: Range,
727	    styles: StyleChain<'a>,
728	) {
729	    let script = styles.get(TextElem::script);
730	    let lang = styles.get(TextElem::lang);
731	    let region = styles.get(TextElem::region);
732	    let mut process = |range: Range, level: BidiLevel| {
733	        let dir = if level.is_ltr() { Dir::LTR } else { Dir::RTL };
734	        let shaped =
735	            shape(engine, range.start, &text[range.clone()], styles, dir, lang, region);
736	        items.push((range, Item::Text(shaped)));
737	    };
738	
739	    let mut prev_level = BidiLevel::ltr();
740	    let mut prev_script = Script::Unknown;
741	    let mut cursor = range.start;
742	
743	    // Group by embedding level and script.  If the text's script is explicitly
744	    // set (rather than inferred from the glyphs), we keep the script at an
745	    // unchanging `Script::Unknown` so that only level changes cause breaks.
746	    for i in range.clone() {
747	        if !text.is_char_boundary(i) {
748	            continue;
749	        }
750	
751	        let level = bidi.levels[i];
752	        let curr_script = match script {
753	            Smart::Auto => {
754	                text[i..].chars().next().map_or(Script::Unknown, |c| c.script())
755	            }
756	            Smart::Custom(_) => Script::Unknown,
757	        };
758	
759	        if level != prev_level || !is_compatible(curr_script, prev_script) {
760	            if cursor < i {
761	                process(cursor..i, prev_level);
762	            }
763	            cursor = i;
764	            prev_level = level;
765	            prev_script = curr_script;
766	        } else if is_generic_script(prev_script) {
767	            prev_script = curr_script;
768	        }
769	    }
770	
771	    process(cursor..range.end, prev_level);
772	}
773	
774	/// Whether this is not a specific script.
775	fn is_generic_script(script: Script) -> bool {
776	    matches!(script, Script::Unknown | Script::Common | Script::Inherited)
777	}
778	
779	/// Whether these script can be part of the same shape run.
780	fn is_compatible(a: Script, b: Script) -> bool {
781	    is_generic_script(a) || is_generic_script(b) || a == b
782	}
