784	/// Shape text into [`ShapedText`].
785	fn shape<'a>(
786	    engine: &Engine,
787	    base: usize,
788	    text: &'a str,
789	    styles: StyleChain<'a>,
790	    dir: Dir,
791	    lang: Lang,
792	    region: Option<Region>,
793	) -> ShapedText<'a> {
794	    let size = styles.resolve(TextElem::size);
795	    let shift_settings = styles.get(TextElem::shift_settings);
796	    let mut ctx = ShapingContext {
797	        world: engine.world,
798	        size,
799	        glyphs: vec![],
800	        used: vec![],
801	        styles,
802	        variant: variant(styles),
803	        features: features(styles),
804	        variations: styles.get_cloned(TextElem::variations),
805	        fallback: styles.get(TextElem::fallback),
806	        dir,
807	        shift_settings,
808	    };
809	
810	    if !text.is_empty() {
811	        shape_segment(&mut ctx, base, text, families(styles));
812	    }
813	
814	    track_and_space(&mut ctx);
815	    calculate_adjustability(&mut ctx, lang, region);
816	
817	    #[cfg(debug_assertions)]
818	    assert_all_glyphs_in_range(&ctx.glyphs, text, base..(base + text.len()));
819	    #[cfg(debug_assertions)]
820	    assert_glyph_ranges_in_order(&ctx.glyphs, dir);
821	
822	    ShapedText {
823	        base,
824	        text,
825	        dir,
826	        lang,
827	        region,
828	        styles,
829	        variant: ctx.variant,
830	        glyphs: Glyphs::from_vec(ctx.glyphs),
831	    }
832	}
