901	pub fn get_font_and_covers<'a, C, F>(
902	    ctx: &mut C,
903	    text: &str,
904	    mut families: impl Iterator<Item = &'a FontFamily>,
905	    mut shape_tofus: F,
906	) -> Option<(FontInstance, Option<&'a Regex>)>
907	where
908	    C: SharedShapingContext<'a>,
909	    F: FnMut(&mut C, &str, FontInstance),
910	{
911	    // Find the next available family.
912	    let world = ctx.world();
913	    let book = world.book();
914	    let mut selection = None;
915	    let mut covers = None;
916	    for family in families.by_ref() {
917	        selection = book
918	            .select(family.as_str(), ctx.variant())
919	            .and_then(|id| world.font(id))
920	            .map(|font| font.instantiate(ctx.variant(), ctx.size(), ctx.variations()))
921	            .filter(|font| !ctx.used().contains(font));
922	        if selection.is_some() {
923	            covers = family.covers();
924	            break;
925	        }
926	    }
927	
928	    // Do font fallback if the families are exhausted and fallback is enabled.
929	    if selection.is_none() && ctx.fallback() {
930	        let first = ctx.first().map(|font| font.info());
931	        selection = book
932	            .select_fallback(first, ctx.variant(), text)
933	            .and_then(|id| world.font(id))
934	            .map(|font| font.instantiate(ctx.variant(), ctx.size(), ctx.variations()))
935	            .filter(|font| !ctx.used().contains(font));
936	    }
937	
938	    // Extract the font id or shape notdef glyphs if we couldn't find any font.
939	    let Some(font) = selection else {
940	        if let Some(font) = ctx.used().first().cloned() {
941	            shape_tofus(ctx, text, font);
942	        }
943	        return None;
944	    };
945	
946	    // This font has been exhausted and will not be used again.
947	    if covers.is_none() {
948	        ctx.used().push(font.clone());
949	    }
950	
951	    Some((font, covers))
952	}
