954	/// Shape text with font fallback using the `families` iterator.
955	fn shape_segment<'a>(
956	    ctx: &mut ShapingContext<'a>,
957	    base: usize,
958	    text: &str,
959	    mut families: impl Iterator<Item = &'a FontFamily> + Clone,
960	) {
961	    // Don't try shaping newlines, tabs, or default ignorables.
962	    if text
963	        .chars()
964	        .all(|c| c == '\n' || c == '\t' || is_default_ignorable(c))
965	    {
966	        return;
967	    }
968	
969	    let Some((font, covers)) =
970	        get_font_and_covers(ctx, text, families.by_ref(), |ctx, text, font| {
971	            shape_tofus(ctx, base, text, &font);
972	        })
973	    else {
974	        return;
975	    };
976	
977	    // Fill the buffer with our text.
978	    let mut buffer = UnicodeBuffer::new();
979	    buffer.push_str(text);
980	    buffer.set_language(language(ctx.styles));
981	    if let Some(script) = ctx.styles.get(TextElem::script).custom().and_then(|script| {
982	        rustybuzz::Script::from_iso15924_tag(Tag::from_bytes(script.as_bytes()))
983	    }) {
984	        buffer.set_script(script);
985	    }
986	    buffer.set_direction(match ctx.dir {
987	        Dir::LTR => rustybuzz::Direction::LeftToRight,
988	        Dir::RTL => rustybuzz::Direction::RightToLeft,
989	        _ => unimplemented!("vertical text layout"),
990	    });
991	    buffer.guess_segment_properties();
992	
993	    // By default, Harfbuzz will create zero-width space glyphs for default
994	    // ignorables. This is probably useful for GUI apps that want noticeable
995	    // effects on the cursor for those, but for us it's not useful and hurts
996	    // text extraction.
997	    buffer.set_flags(BufferFlags::REMOVE_DEFAULT_IGNORABLES);
998	
999	    let (script_shift, script_compensation, scale, shift_feature) = ctx
1000	        .shift_settings
1001	        .map_or((Em::zero(), Em::zero(), Em::one(), None), |settings| {
1002	            determine_shift(text, &font, settings)
1003	        });
1004	
1005	    let has_shift_feature = shift_feature.is_some();
1006	    if let Some(feat) = shift_feature {
1007	        // Temporarily push the feature.
1008	        ctx.features.push(feat);
1009	    }
1010	
1011	    // Prepare the shape plan. This plan depends on direction, script, language,
1012	    // and features, but is independent from the text and can thus be memoized.
1013	    let plan = create_shape_plan(
1014	        &font,
1015	        buffer.direction(),
1016	        buffer.script(),
1017	        buffer.language().as_ref(),
1018	        &ctx.features,
1019	    );
1020	
1021	    if has_shift_feature {
1022	        ctx.features.pop();
1023	    }
1024	
1025	    // Shape!
1026	    let buffer = rustybuzz::shape_with_plan(font.rusty(), &plan, buffer);
1027	    let infos = buffer.glyph_infos();
1028	    let pos = buffer.glyph_positions();
1029	    let ltr = ctx.dir.is_positive();
1030	
1031	    // Whether the character at the given offset is covered by the coverage.
1032	    let is_covered = |offset| {
1033	        let end = text[offset..]
1034	            .char_indices()
1035	            .nth(1)
1036	            .map(|(i, _)| offset + i)
1037	            .unwrap_or(text.len());
1038	        covers.is_none_or(|cov| cov.is_match(&text[offset..end]))
1039	    };
1040	
1041	    // Collect the shaped glyphs, doing fallback and shaping parts again with
1042	    // the next font if necessary.
1043	    let mut i = 0;
1044	    while i < infos.len() {
1045	        let info = &infos[i];
1046	        let cluster = info.cluster as usize;
1047	
1048	        // Add the glyph to the shaped output.
1049	        if info.glyph_id != 0 && is_covered(cluster) {
1050	            // Assume we have the following sequence of (glyph_id, cluster):
1051	            // [(120, 0), (80, 0), (3, 3), (755, 4), (69, 4), (424, 13),
1052	            //  (63, 13), (193, 25), (80, 25), (3, 31)
1053	            //
1054	            // We then want the sequence of (glyph_id, text_range) to look as follows:
1055	            // [(120, 0..3), (80, 0..3), (3, 3..4), (755, 4..13), (69, 4..13),
1056	            //  (424, 13..25), (63, 13..25), (193, 25..31), (80, 25..31), (3, 31..x)]
1057	            //
1058	            // Each glyph in the same cluster should be assigned the full text
1059	            // range. This is necessary because only this way krilla can
1060	            // properly assign `ActualText` attributes in complex shaping
1061	            // scenarios.
1062	
1063	            // The start of the glyph's text range.
1064	            let start = base + cluster;
1065	
1066	            // Determine the end of the glyph's text range.
1067	            let mut k = i;
1068	            let step: isize = if ltr { 1 } else { -1 };
1069	            let end = loop {
1070	                // If we've reached the end of the glyphs, the `end` of the
1071	                // range should be the end of the full text.
1072	                let Some((next, next_info)) = k
1073	                    .checked_add_signed(step)
1074	                    .and_then(|n| infos.get(n).map(|info| (n, info)))
1075	                else {
1076	                    break base + text.len();
1077	                };
1078	
1079	                // If the cluster doesn't match anymore, we've reached the end.
1080	                if next_info.cluster != info.cluster {
1081	                    break base + next_info.cluster as usize;
1082	                }
1083	
1084	                k = next;
1085	            };
1086	
1087	            let c = text[cluster..].chars().next().unwrap();
1088	            let script = c.script();
1089	            let x_advance = font.to_em(pos[i].x_advance);
1090	            ctx.glyphs.push(ShapedGlyph {
1091	                font: font.clone(),
1092	                glyph_id: info.glyph_id as u16,
1093	                // TODO: Don't ignore y_advance.
1094	                x_advance,
1095	                x_offset: font.to_em(pos[i].x_offset) + script_compensation,
1096	                y_offset: font.to_em(pos[i].y_offset) + script_shift,
1097	                size: scale.at(ctx.size),
1098	                adjustability: Adjustability::default(),
1099	                range: start..end,
1100	                safe_to_break: !info.unsafe_to_break(),
1101	                c,
1102	                is_justifiable: is_justifiable(
1103	                    c,
1104	                    script,
1105	                    x_advance,
1106	                    Adjustability::default().stretchability,
1107	                ),
1108	                script,
1109	            });
1110	        } else {
1111	            // First, search for the end of the tofu sequence.
1112	            let k = i;
1113	            while infos.get(i + 1).is_some_and(|info| {
1114	                info.glyph_id == 0 || !is_covered(info.cluster as usize)
1115	            }) {
1116	                i += 1;
1117	            }
1118	
1119	            // Then, determine the start and end text index for the tofu
1120	            // sequence.
1121	            //
1122	            // Examples:
1123	            // Everything is shown in visual order. Tofus are written as "_".
1124	            // We want to find out that the tofus span the text `2..6`.
1125	            // Note that the clusters are longer than 1 char.
1126	            //
1127	            // Left-to-right:
1128	            // Text:     h a l i h a l l o
1129	            // Glyphs:   A   _   _   C   E
1130	            // Clusters: 0   2   4   6   8
1131	            //              k=1 i=2
1132	            //
1133	            // Right-to-left:
1134	            // Text:     O L L A H I L A H
1135	            // Glyphs:   E   C   _   _   A
1136	            // Clusters: 8   6   4   2   0
1137	            //                  k=2 i=3
1138	            let start = infos[if ltr { k } else { i }].cluster as usize;
1139	            let end = if ltr { i.checked_add(1) } else { k.checked_sub(1) }
1140	                .and_then(|last| infos.get(last))
1141	                .map_or(text.len(), |info| info.cluster as usize);
1142	
1143	            // Trim half-baked cluster.
1144	            let remove = base + start..base + end;
1145	            while ctx.glyphs.last().is_some_and(|g| remove.contains(&g.range.start)) {
1146	                ctx.glyphs.pop();
1147	            }
1148	
1149	            // Recursively shape the tofu sequence with the next family.
1150	            shape_segment(ctx, base + start, &text[start..end], families.clone());
1151	        }
1152	
1153	        i += 1;
1154	    }
1155	
1156	    ctx.used.pop();
1157	}
1158	
1159	/// Returns a `(script_shift, script_compensation, scale, feature)` quadruplet
1160	/// describing how to produce scripts.
1161	///
1162	/// Those values determine how the rendered text should be transformed to
1163	/// display sub-/super-scripts. If the OpenType feature can be used, the
1164	/// rendered text should not be transformed in any way, and so those values are
1165	/// neutral (`(0, 0, 1, None)`). If scripts should be synthesized, those values
1166	/// determine how to transform the rendered text to display scripts as expected.
1167	fn determine_shift(
1168	    text: &str,
1169	    font: &FontInstance,
1170	    settings: ShiftSettings,
1171	) -> (Em, Em, Em, Option<Feature>) {
1172	    settings
1173	        .typographic
1174	        .then(|| {
1175	            // If typographic scripts are enabled (i.e., we want to use the
1176	            // OpenType feature instead of synthesizing if possible), we add
1177	            // "subs"/"sups" to the feature list if supported by the font.
1178	            // In case of a problem, we just early exit
1179	            let gsub = font.rusty().tables().gsub?;
1180	            let lookups = gsub.features.find(settings.kind.feature())?.lookup_indices;
1181	            text.chars()
1182	                .all(|c| {
1183	                    let Some(i) = font.rusty().glyph_index(c) else { return false };
1184	                    lookups
1185	                        .into_iter()
1186	                        .filter_map(|i| gsub.lookups.get(i))
1187	                        .flat_map(|lookup| {
1188	                            lookup.subtables.into_iter::<SubstitutionSubtable>()
1189	                        })
1190	                        .any(|subtable| subtable.coverage().contains(i))
1191	                })
1192	                .then(|| {
1193	                    // If we can use the OpenType feature, we can keep the text
1194	                    // as is.
1195	                    (
1196	                        Em::zero(),
1197	                        Em::zero(),
1198	                        Em::one(),
1199	                        Some(Feature::new(settings.kind.feature(), 1, ..)),
1200	                    )
1201	                })
1202	        })
1203	        // Reunite the cases where `typographic` is `false` or where using the
1204	        // OpenType feature would not work.
1205	        .flatten()
1206	        .unwrap_or_else(|| {
1207	            let script_metrics = settings.kind.read_metrics(font.metrics());
1208	            (
1209	                settings.shift.unwrap_or(script_metrics.vertical_offset),
1210	                script_metrics.horizontal_offset,
1211	                settings.size.unwrap_or(script_metrics.height),
1212	                None,
1213	            )
1214	        })
1215	}
