1235	/// Shape the text with tofus from the given font.
1236	fn shape_tofus(ctx: &mut ShapingContext, base: usize, text: &str, font: &FontInstance) {
1237	    let x_advance = font.x_advance(0).unwrap_or_default();
1238	    let add_glyph = |(cluster, c): (usize, char)| {
1239	        let start = base + cluster;
1240	        let end = start + c.len_utf8();
1241	        let script = c.script();
1242	        ctx.glyphs.push(ShapedGlyph {
1243	            font: font.clone(),
1244	            glyph_id: 0,
1245	            x_advance,
1246	            x_offset: Em::zero(),
1247	            y_offset: Em::zero(),
1248	            size: ctx.size,
1249	            adjustability: Adjustability::default(),
1250	            range: start..end,
1251	            safe_to_break: true,
1252	            c,
1253	            is_justifiable: is_justifiable(
1254	                c,
1255	                script,
1256	                x_advance,
1257	                Adjustability::default().stretchability,
1258	            ),
1259	            script,
1260	        });
1261	    };
1262	    if ctx.dir.is_positive() {
1263	        text.char_indices().for_each(add_glyph);
1264	    } else {
1265	        text.char_indices().rev().for_each(add_glyph);
1266	    }
1267	}
