1269	/// Apply tracking and spacing to the shaped glyphs.
1270	fn track_and_space(ctx: &mut ShapingContext) {
1271	    let tracking = Em::from_abs(ctx.styles.resolve(TextElem::tracking), ctx.size);
1272	    let spacing = ctx
1273	        .styles
1274	        .resolve(TextElem::spacing)
1275	        .map(|abs| Em::from_abs(abs, ctx.size));
1276	
1277	    let mut glyphs = ctx.glyphs.iter_mut().peekable();
1278	    while let Some(glyph) = glyphs.next() {
1279	        // Make non-breaking space same width as normal space.
1280	        if glyph.c == '\u{00A0}' {
1281	            glyph.x_advance -= nbsp_delta(&glyph.font).unwrap_or_default();
1282	        }
1283	
1284	        if glyph.is_space() {
1285	            glyph.x_advance = spacing.relative_to(glyph.x_advance);
1286	        }
1287	
1288	        if glyphs
1289	            .peek()
1290	            .is_some_and(|next| glyph.range.start != next.range.start)
1291	        {
1292	            glyph.x_advance += tracking;
1293	        }
1294	    }
1295	}
1296	
1297	/// Calculate stretchability and shrinkability of each glyph,
1298	/// and CJK punctuation adjustments according to Chinese Layout Requirements.
1299	fn calculate_adjustability(ctx: &mut ShapingContext, lang: Lang, region: Option<Region>) {
1300	    let style = cjk_punct_style(lang, region);
1301	    let limits = ctx.styles.get(ParElem::justification_limits);
1302	    let font_size = ctx.size;
1303	
1304	    let mut glyphs = ctx.glyphs.iter_mut().peekable();
1305	    while let Some(glyph) = glyphs.next() {
1306	        // Do not apply adjustability to a glyph if there is another one in the
1307	        // same cluster.
1308	        let stretchable =
1309	            glyphs.peek().is_none_or(|next| glyph.range.start != next.range.start);
1310	
1311	        glyph.adjustability =
1312	            glyph.base_adjustability(style, &limits, font_size, stretchable);
1313	    }
1314	
1315	    let mut glyphs = ctx.glyphs.iter_mut().peekable();
1316	    while let Some(glyph) = glyphs.next() {
1317	        // CNS style needs not further adjustment.
1318	        if glyph.is_cjk_punctuation() && matches!(style, CjkPunctStyle::Cns) {
1319	            continue;
1320	        }
1321	
1322	        // Now we apply consecutive punctuation adjustment, specified in Chinese Layout.
1323	        // Requirements, section 3.1.6.1 Punctuation Adjustment Space, and Japanese Layout
1324	        // Requirements, section 3.1 Line Composition Rules for Punctuation Marks
1325	        let Some(next) = glyphs.peek_mut() else { continue };
1326	        let width = glyph.x_advance;
1327	        let delta = width / 2.0;
1328	        if glyph.is_cjk_punctuation()
1329	            && next.is_cjk_punctuation()
1330	            && (glyph.shrinkability().1 + next.shrinkability().0) >= delta
1331	        {
1332	            let left_delta = glyph.shrinkability().1.min(delta);
1333	            glyph.shrink_right(left_delta);
1334	            next.shrink_left(delta - left_delta);
1335	        }
1336	    }
1337	}
