1339	/// Difference between non-breaking and normal space.
1340	fn nbsp_delta(font: &FontInstance) -> Option<Em> {
1341	    let space = font.ttf().glyph_index(' ')?.0;
1342	    let nbsp = font.ttf().glyph_index('\u{00A0}')?.0;
1343	    Some(font.x_advance(nbsp)? - font.x_advance(space)?)
1344	}
