1346	/// Returns true if all glyphs in `glyphs` have ranges within the range `range`.
1347	#[cfg(debug_assertions)]
1348	fn assert_all_glyphs_in_range(glyphs: &[ShapedGlyph], text: &str, range: Range) {
1349	    if glyphs
1350	        .iter()
1351	        .any(|g| g.range.start < range.start || g.range.end > range.end)
1352	    {
1353	        panic!("one or more glyphs in {text:?} fell out of range");
1354	    }
1355	}
