1357	/// Asserts that the ranges of `glyphs` is in the proper order according to
1358	/// `dir`.
1359	///
1360	/// This asserts instead of returning a bool in order to provide a more
1361	/// informative message when the invariant is violated.
1362	#[cfg(debug_assertions)]
1363	fn assert_glyph_ranges_in_order(glyphs: &[ShapedGlyph], dir: Dir) {
1364	    if glyphs.is_empty() {
1365	        return;
1366	    }
1367	
1368	    // Iterator::is_sorted and friends are unstable as of Rust 1.70.0
1369	    for i in 0..(glyphs.len() - 1) {
1370	        let a = &glyphs[i];
1371	        let b = &glyphs[i + 1];
1372	        let ord = a.range.start.cmp(&b.range.start);
1373	        let ord = if dir.is_positive() { ord } else { ord.reverse() };
1374	        if ord == std::cmp::Ordering::Greater {
1375	            panic!(
1376	                "glyph ranges should be monotonically {}, \
1377	                 but found glyphs out of order:\n\n\
1378	                 first: {a:#?}\nsecond: {b:#?}",
1379	                if dir.is_positive() { "increasing" } else { "decreasing" },
1380	            );
1381	        }
1382	    }
1383	}
