1385	// The CJK punctuation that can appear at the beginning or end of a line.
1386	pub const BEGIN_PUNCT_PAT: &[char] =
1387	    &['“', '‘', '《', '〈', '（', '『', '「', '【', '〖', '〔', '［', '｛'];
1388	pub const END_PUNCT_PAT: &[char] = &[
1389	    '”', '’', '，', '．', '。', '、', '：', '；', '》', '〉', '）', '』', '」', '】',
1390	    '〗', '〕', '］', '｝', '？', '！',
