1393	#[derive(Debug, Copy, Clone, Eq, PartialEq)]
1394	pub enum CjkPunctStyle {
1395	    /// Standard GB/T 15834-2011, used mostly in mainland China.
1396	    Gb,
1397	    /// Standard by Taiwan Ministry of Education, used in Taiwan and Hong Kong.
1398	    Cns,
1399	    /// Standard JIS X 4051, used in Japan.
1400	    Jis,
1401	}
