1403	pub fn cjk_punct_style(lang: Lang, region: Option<Region>) -> CjkPunctStyle {
1404	    match (lang, region.as_ref().map(Region::as_str)) {
1405	        (Lang::CHINESE, Some("TW" | "HK")) => CjkPunctStyle::Cns,
1406	        (Lang::JAPANESE, _) => CjkPunctStyle::Jis,
1407	        // zh-CN, zh-SG, zh-MY use GB-style punctuation,
1408	        _ => CjkPunctStyle::Gb,
1409	    }
1410	}
