1412	/// Whether the glyph is a space.
1413	fn is_space(c: char) -> bool {
1414	    matches!(c, ' ' | '\u{00A0}' | '　')
1415	}
1416	
1417	/// Whether the glyph is part of Chinese or Japanese script (i.e. CJ, not CJK).
1418	pub fn is_of_cj_script(c: char) -> bool {
1419	    is_cj_script(c, c.script())
1420	}
1421	
1422	/// Whether the glyph is part of Chinese or Japanese script (i.e. CJ, not CJK).
1423	/// The function is dedicated to typesetting Chinese or Japanese, which do not
1424	/// have spaces between words, so K is not checked here.
1425	fn is_cj_script(c: char, script: Script) -> bool {
1426	    use Script::*;
1427	    // U+30FC: Katakana-Hiragana Prolonged Sound Mark
1428	    matches!(script, Hiragana | Katakana | Han) || c == '\u{30FC}'
1429	}
