1431	/// See <https://www.w3.org/TR/clreq/#punctuation_width_adjustment>
1432	fn is_cjk_left_aligned_punctuation(
1433	    c: char,
1434	    x_advance: Em,
1435	    stretchability: (Em, Em),
1436	    style: CjkPunctStyle,
1437	) -> bool {
1438	    use CjkPunctStyle::*;
1439	
1440	    // CJK quotation marks shares codepoints with latin quotation marks.
1441	    // But only the CJK ones have full width.
1442	    if matches!(c, '”' | '’') && x_advance + stretchability.1 == Em::one() {
1443	        return true;
1444	    }
1445	
1446	    if matches!(style, Gb | Jis) && matches!(c, '，' | '。' | '．' | '、' | '：' | '；')
1447	    {
1448	        return true;
1449	    }
1450	
1451	    if matches!(style, Gb) && matches!(c, '？' | '！') {
1452	        // In GB style, exclamations and question marks are also left aligned
1453	        // and can be adjusted. Note that they are not adjustable in other
1454	        // styles.
1455	        return true;
1456	    }
1457	
1458	    // See appendix A.3 https://www.w3.org/TR/clreq/#tables_of_chinese_punctuation_marks
1459	    matches!(c, '》' | '）' | '』' | '」' | '】' | '〗' | '〕' | '〉' | '］' | '｝')
1460	}
1461	
1462	/// See <https://www.w3.org/TR/clreq/#punctuation_width_adjustment>
1463	fn is_cjk_right_aligned_punctuation(
1464	    c: char,
1465	    x_advance: Em,
1466	    stretchability: (Em, Em),
1467	) -> bool {
1468	    // CJK quotation marks shares codepoints with latin quotation marks.
1469	    // But only the CJK ones have full width.
1470	    if matches!(c, '“' | '‘') && x_advance + stretchability.0 == Em::one() {
1471	        return true;
1472	    }
1473	    // See appendix A.3 https://www.w3.org/TR/clreq/#tables_of_chinese_punctuation_marks
1474	    matches!(c, '《' | '（' | '『' | '「' | '【' | '〖' | '〔' | '〈' | '［' | '｛')
1475	}
1476	
1477	/// See <https://www.w3.org/TR/clreq/#punctuation_width_adjustment>
1478	fn is_cjk_center_aligned_punctuation(c: char, style: CjkPunctStyle) -> bool {
1479	    if matches!(style, CjkPunctStyle::Cns)
1480	        && matches!(c, '，' | '。' | '．' | '、' | '：' | '；')
1481	    {
1482	        return true;
1483	    }
1484	
1485	    // U+30FB: Katakana Middle Dot
1486	    // U+00B7: Middle Dot
1487	    matches!(c, '\u{30FB}' | '\u{00B7}')
1488	}
1489	
1490	/// Whether the glyph is justifiable.
1491	///
1492	/// Quotations in latin script and CJK are unfortunately the same codepoint
1493	/// (U+2018, U+2019, U+201C, U+201D), but quotations in Chinese must be
1494	/// fullwidth. This heuristics can therefore fail for monospace latin fonts.
1495	/// However, since monospace fonts are usually not justified this edge case
1496	/// should be rare enough.
1497	fn is_justifiable(
1498	    c: char,
1499	    script: Script,
1500	    x_advance: Em,
1501	    stretchability: (Em, Em),
1502	) -> bool {
1503	    // punctuation style is not relevant here.
1504	    let style = CjkPunctStyle::Gb;
1505	    is_space(c)
1506	        || is_cj_script(c, script)
1507	        || is_cjk_left_aligned_punctuation(c, x_advance, stretchability, style)
1508	        || is_cjk_right_aligned_punctuation(c, x_advance, stretchability)
1509	        || is_cjk_center_aligned_punctuation(c, style)
1510	}
